#!/usr/bin/env bash
# generated by codeguard v<plugin-version> — delete this line to take ownership
#
# Definition-of-Done Stop hook for Claude Code: blocks the agent from
# ending its turn while the project's checks are red, with bounded retries
# so a check that can't be fixed (flaky test, broken linter) can't trap
# the session in an infinite loop.
#
# Template placeholders to fill in at setup time:
#   <plugin-version>      — codeguard plugin version, from plugin.json
#   <lint command>        — e.g. `pnpm lint`
#   <type-check command>  — e.g. `pnpm typecheck`; drop it if the stack
#                           has no type checker — never leave a
#                           placeholder behind
#   <test command>        — e.g. `pnpm test`
#
# Deliberately no `set -e`: this script's entire job is to inspect the
# exit status of the checks below and act on failure, and -e fights that —
# it terminates the script the instant anything returns non-zero
# (including a `grep` that legitimately finds no match on a freshly
# created state file), before the attempt counter or cleanup logic ever
# runs. `-u`/`pipefail` don't have that failure mode, so they stay on.
set -uo pipefail

STATE_DIR="$CLAUDE_PROJECT_DIR/.claude"
# Mutable per-session state — keep this path gitignored (setup adds a
# `.claude/.dod-attempts` line to .gitignore).
STATE_FILE="$STATE_DIR/.dod-attempts"
MAX_ATTEMPTS=3

mkdir -p "$STATE_DIR"
touch "$STATE_FILE"

# Parse session_id from the hook payload on stdin. Prefer jq, but don't
# require it — a missing tool must never turn this hook into an error on
# every turn.
payload=$(cat)
if command -v jq >/dev/null 2>&1; then
  session_id=$(printf '%s' "$payload" | jq -r '.session_id // empty' 2>/dev/null)
else
  session_id=$(printf '%s' "$payload" | sed -n 's/.*"session_id"[[:space:]]*:[[:space:]]*"\([^"]*\)".*/\1/p')
fi
session_id=${session_id:-unknown-session}

attempts=$(awk -F: -v id="$session_id" '$1 == id { print $2 }' "$STATE_FILE")
attempts=${attempts:-0}

# Inline the actual check commands in this condition — don't wrap them in
# a helper function. Older bash (macOS's stock /bin/bash is still 3.2)
# doesn't reliably suspend errexit semantics for a function called as an
# if/while condition, and this script must not depend on that.
if <lint command> && <type-check command> && <test command>; then
  grep -v "^${session_id}:" "$STATE_FILE" > "${STATE_FILE}.tmp"
  mv "${STATE_FILE}.tmp" "$STATE_FILE"
  exit 0
fi

attempts=$((attempts + 1))
{ grep -v "^${session_id}:" "$STATE_FILE"; echo "${session_id}:${attempts}"; } > "${STATE_FILE}.tmp"
mv "${STATE_FILE}.tmp" "$STATE_FILE"

if [ "$attempts" -ge "$MAX_ATTEMPTS" ]; then
  # Give up blocking — surface the failure without trapping the session.
  echo "{\"hookSpecificOutput\":{\"hookEventName\":\"Stop\",\"additionalContext\":\"DoD checks still failing after $MAX_ATTEMPTS attempts — releasing. Checks remain red; fix before pushing.\"}}"
  exit 0
fi

echo "DoD checks failed (attempt $attempts/$MAX_ATTEMPTS) — fix and finish." >&2
exit 2
